cd /app/submission && cat > /workspace/tmp/t6.py << 'PY'
import subprocess, json, sys
def run(obj):
    p=subprocess.run([sys.executable,'-I','/app/submission/entry.py'],input=json.dumps(obj).encode(),capture_output=True)
    try: return json.loads(p.stdout.decode())
    except: return {'_raw':p.stdout.decode(),'_err':p.stderr.decode()}
def cfg(**kw):
    base=dict(early=True,overlap="reject",buffer_packets=4,idle_ms=0,
              max_streams_bidi=100,max_streams_uni=100,max_stream_data=65536,
              max_data=1000000000,crypto_limit=65536,sent={"I":[],"H":[],"A":[]})
    base.update(kw); return base
def req(traces): return {"version":1,"traces":traces}
def tr(tid,config,events): return {"id":tid,"config":config,"events":events}
def P(level,pn,frames,auth=True): return {"level":level,"pn":pn,"auth":auth,"frames":frames}
def D(t,bytes,packets): return {"t":t,"op":"datagram","bytes":bytes,"packets":packets}
setup_A={"t":0,"op":"key","level":"A","action":"install"}
tests={}
# zero frames
tests['zero_frames']=req([tr("a",cfg(),[D(0,1200,[P("I",0,[])])])])
# CLOSE then forbidden frame -> preflight error
tests['close_then_bad']=req([tr("a",cfg(),[setup_A,D(1,1200,[P("A",0,[{"type":"CLOSE","app":True,"code":7},{"type":"HANDSHAKE_DONE"}])])])])
# ACK at Z forbidden
tests['ack_z']=req([tr("a",cfg(early=True),[
  D(1,1200,[P("Z",0,[{"type":"ACK","ranges":[[0,0]]}])]),
])])
# PADDING at Z allowed
tests['pad_z']=req([tr("a",cfg(early=True),[D(1,1200,[P("Z",0,[{"type":"PADDING"}])])])])
# CRYPTO at Z forbidden
tests['crypto_z']=req([tr("a",cfg(early=True),[D(1,1200,[P("Z",0,[{"type":"CRYPTO","offset":0,"data_hex":"aa"}])])])])
# CLOSE transport at I
tests['close_i']=req([tr("a",cfg(),[D(1,1200,[P("I",0,[{"type":"CLOSE","app":False,"code":9}])])])])
# STOP at uni (id=2) wrong dir
tests['stop_uni']=req([tr("a",cfg(),[setup_A,D(1,1200,[P("A",0,[{"type":"STOP_SENDING","id":2}])])])])
# RESET at uni allowed (id=2)
tests['reset_uni']=req([tr("a",cfg(),[setup_A,D(1,1200,[P("A",0,[{"type":"RESET_STREAM","id":2,"final_size":3}])])])])
for name,obj in tests.items():
    print("====",name); print(json.dumps(run(obj)))
